import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class TcPolicy {
    public String profile(boolean needsRealDb, boolean hasDocker, int ciMinutes) {
        if (!needsRealDb) return "unit";
        if (hasDocker && ciMinutes >= 8) return "integration-tc";
        return "integration-mock";
    }
}

public class TcPolicyTest {
    @Test void tcPath() { assertEquals("integration-tc", new TcPolicy().profile(true, true, 12)); }
    @Test void mockWhenNoDocker() { assertEquals("integration-mock", new TcPolicy().profile(true, false, 12)); }
    @Test void mockWhenBudgetLow() { assertEquals("integration-mock", new TcPolicy().profile(true, true, 5)); }
    @Test void unitPath() { assertEquals("unit", new TcPolicy().profile(false, true, 20)); }
}
